INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(39991, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done, $N. I see you\'re not only skilled but cunning.', 0),
(39992, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'ve done more in a day than these idiots around me have done in a month. I shall make sure you\'re properly compensated for your services.$B$BDo not mistake my generosity for weakness however. If you were to make a move against me, you\'d be dead just as quick as that prince. I don\'t want you getting any ideas.', 0),
(39993, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, you did it already? Good, good. Now find something else to do and get out of my face.', 0),
(40014, 0, 0, 0, 0, 0, 0, 0, 0, 'You returned faster than I thought you would, perhaps you are a proven hunter. You fit in well with my people, but there is one more thing to do in preparation.', 0),
(40015, 0, 0, 0, 0, 0, 0, 0, 0, 'You truly are a master hunter and a friend to the Wildtusk, $N! Take this for all of your help, thank you!', 0),
(40016, 0, 0, 0, 0, 0, 0, 0, 0, 'Raaaar!', 0),
(40017, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'ve done all of Wildtusk Village a favor this day, thank you. Take this silver as payment for your help.', 0),
(40018, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'ve done it, $C! We may rest easy tonight thanks to the work you\'ve done. Take these coins as appreciation for the work you\'ve done.', 0),
(40019, 0, 0, 0, 0, 0, 0, 0, 0, 'With the charms returned to us, we can begin to tend to the spirits once again. I can already feel the difference. Thank you for all you have done, $C!', 0),
(40020, 0, 0, 0, 0, 0, 0, 0, 0, 'I cannot believe my eyes, $C. Thank you for retrieving it for me. I can now return to my duties with pride.', 0),
(40021, 0, 0, 0, 0, 0, 0, 0, 0, 'He deserved worse than this, $C. What you see here are the remnants of my people, and he will pay for his crimes even after death now that you have brought me his head.', 0),
(40022, 0, 0, 0, 0, 0, 0, 0, 0, 'He will join Gan\'to and suffer until the day I die, $C. The two of them will decorate my belt forevermore and stand as a symbol of victory over the Witherbark and newfound friendship with the Horde. You have done well, $N. Your deeds will be remembered by my people forever.', 0),
(40023, 0, 0, 0, 0, 0, 0, 0, 0, 'You desire to aid the realm of rock? There is much to do. Let us begin.', 0),
(40024, 0, 0, 0, 0, 0, 0, 0, 0, 'There is something foul here—a magic that is not native to my kind.', 0),
(40025, 0, 0, 0, 0, 0, 0, 0, 0, 'This is everything. I shall do as Lord Rog instructed so that he may purify the bracers.', 0),
(40026, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done your duty well. You exemplify the values of my kind. Without you, I would be unable to continue my work. Take this signet as a symbol of gratitude, mortal. May the blessings of the Elemental Plane help you in your future battles.', 0),
(40181, 0, 0, 0, 0, 0, 0, 0, 0, 'Their ship, the Harbinger, was sent fer some reason in Arathi Highlands. We dunno why, \'n we mighty don\'t care that much either. All we care about right now be that they be dead, \'n we\'ve landed once again a blow to the Blackwater Pirates.', 0),
(40448, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, hello there, this is from mom? I miss her quite a bit, but it\'s nice seeing family! The city is kind of fascinating too.', 0),
(40449, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, well my my, you\'ve really outdone yourself for us. Perhaps now we can finally get a plentiful harvest in for the season, here, take this, as a token of my thanks, its a spare.', 0),
(40450, 0, 0, 0, 0, 0, 0, 0, 0, '<After inserting the Gold Power Core it takes a moment for Chaser to power up once again, the machine whirrs to life, beeping happily.>', 0),
(40451, 0, 0, 0, 0, 0, 0, 0, 0, 'You make Stromgarde proud, the less trolls, the better for our ultimate survival.', 0),
(40452, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done well, much better than I would have expected. Take this, as a thanks.', 0),
(40453, 0, 0, 0, 0, 0, 0, 0, 0, 'The Ogres are a mighty foe, and although you\'ve done excellent work, I fear it will not be enough. Here, as I promised.', 0),
(40454, 0, 0, 0, 0, 0, 0, 0, 0, 'Do I know you, is there something that I can help you with?', 0),
(40455, 0, 0, 0, 0, 0, 0, 0, 0, 'Old Farwell has done a lot for us. Thank you for delivering this ring, it should be just what we needed.', 0),
(40511, 0, 0, 0, 0, 0, 0, 0, 0, 'A magical grain you say? Its been a long time since I\'ve heard about it.', 0),
(40512, 0, 0, 0, 0, 0, 0, 0, 0, 'You found it! Her recovery will be slow but I believe she\'ll back on the road hunting trolls with our cavalrymen in no time. This is all I have in my pockets, even if not much you made this old handler happy today. Thank you.', 0),
(60132, 11, 0, 0, 0, 0, 0, 0, 0, 'Azeroth is a far better place with less spiders alive in it.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(39991, 1, 1, 'What did I say about returning to me before it\'s done?', 0),
(39992, 1, 1, 'What did I say about returning to me before it\'s done?', 0),
(39993, 1, 1, 'Well? I\'m waiting...', 0),
(40014, 0, 0, 'Have you gathered the venom sacs?', 0),
(40015, 0, 0, 'Has she been slain?', 0),
(40016, 0, 0, 'Have you smashed ogre for my beads?', 0),
(40017, 0, 0, 'Have you gathered the war materials?', 0),
(40018, 0, 0, 'Have you cut down their numbers?', 0),
(40019, 0, 0, 'Have you retrieved the charms?', 0),
(40020, 0, 0, 'Have you found the amulet?', 0),
(40021, 0, 0, 'Have you put an end to that traitor\'s miserable life?', 0),
(40022, 0, 0, 'Are those drums of mourning?', 0),
(40023, 0, 0, 'Yes, mortal being?', 0),
(40024, 0, 0, 'Is it done, mortal? Have you gathered the bracers?', 0),
(40025, 0, 0, 'The task at hand is an important one, mon. We must be doing our best to help the elementals.', 0),
(40181, 0, 0, 'Been a long road, eh?', 0),
(40448, 0, 0, 'Yes, can I help you?', 0),
(40449, 0, 0, 'Have you had any luck just yet?', 0),
(40450, 0, 0, 'Beeeeep!', 0),
(40451, 0, 0, 'Has the deed been done $C?', 0),
(40452, 0, 0, 'It may be hard to find the pass, but I am sure you will do what is neccesary.', 0),
(40453, 0, 0, 'Has the work been done?', 0),
(40454, 0, 0, 'Yes?', 0),
(40455, 0, 0, 'Yes?', 0),
(40511, 0, 0, 'Hello, welcome to Refuge Point. How can I help you?', 0),
(40512, 0, 0, 'I don\'t know how much longer she can last.', 0),
(60132, 4, 48, 'Eight legs is too many.', 0);
